    check('Quality percentages replace rather than multiply and one flaw applies last',s['durability']['positivePercentChoices']==[0,25,50] and s['durability']['persistentFlawAppliedLast'] and not s['durability']['repeatedFlawHalvesAgain'] and not s['durability']['repairCompoundsDurability'] and not s['durability']['qualityChangesPotency'])
    check('Durability worked cases preserve actual damage and prior flaws',project_durability(5,0,False,3,25)=={'ordinaryMaximumHP':5,'positiveDurabilityPercent':25,'persistentFlaw':False,'maximumHP':6,'currentHP':4} and project_durability(20,25,True,9,50)=={'ordinaryMaximumHP':20,'positiveDurabilityPercent':50,'persistentFlaw':True,'maximumHP':15,'currentHP':12} and project_durability(5,0,False,1,0,True)['currentHP']==0 and project_durability(5,50,True,3,25,True)['maximumHP']==3)
    cases=0;conservation=True
